s1_l = v1_l;
// Stage 2
v2_l = g * v1_l + (1 - g) * s2_l;
s2_l = v2_l;
// Stage 3
v3_l = g * v2_l + (1 - g) * s3_l;
s3_l = v3_l;
// Stage 4
v4_l = g * v3_l + (1 - g) * s4_l;
s4_l = v4_l;
spl0 = v4_l * out_gain;

// --- Right channel ---
in_r = spl1 * drive_lin;
fb_r = tanh(s4_r * k);
v1_r = g * (in_r - fb_r) + (1 - g) * s1_r;
s1_r = v1_r;
